"""Document checks: generated bytes, original evidence, shell syntax, real installed CLI and browser."""
import argparse
import ast
from hashlib import sha256
from html.parser import HTMLParser
import json
import os
from pathlib import Path
import subprocess
import sys

from report_common import ROOT, OUT, NAMES

ASSETS = Path('/data/Users/zrh/data/hhu-ai-avatar')
HERE = Path(__file__).resolve().parent


def digest(path):
    return sha256(path.read_bytes()).hexdigest()


class CodeBlocks(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.active = False
        self.blocks = []
        self.current = []

    def handle_starttag(self, tag, attrs):
        if tag == 'pre':
            self.active = True
            self.current = []

    def handle_data(self, data):
        if self.active:
            self.current.append(data)

    def handle_endtag(self, tag):
        if tag == 'pre':
            self.blocks.append(''.join(self.current))
            self.active = False


def main():
    p = argparse.ArgumentParser()
    p.add_argument('--version', type=int, required=True)
    args = p.parse_args()
    raw = ASSETS/f'artifacts/reports/2026-11-21/qa-v{args.version}'
    proof_path = HERE/f'报告质量核验-v{args.version}.json'
    assert not raw.exists() and not proof_path.exists()
    raw.parent.mkdir(parents=True, exist_ok=True)
    proof = dict(passed=False, whole_stage_deadline=None, source_ref=subprocess.check_output(
        ['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(), source_sha256={}, steps=[])
    for path in [*(HERE.glob('*.py')), HERE/'qa_reports.cjs', *(OUT/name for name in NAMES), HERE/'历史资料与提交清单.json']:
        proof['source_sha256'][str(path.relative_to(ROOT))] = digest(path)
    try:
        for path in HERE.glob('*.py'):
            ast.parse(path.read_text())
        result = subprocess.run([sys.executable, '-B', str(HERE/'render_reports.py'), '--check'], cwd=ROOT,
                                text=True, capture_output=True)
        proof['steps'].append(dict(name='deterministic_render', actual_returncode=result.returncode))
        assert result.returncode == 0, result.stderr
        inventory = json.loads((HERE/'历史资料与提交清单.json').read_text())
        for name, value in inventory['source_sha256'].items():
            assert digest(ROOT/name) == value, 'Historical source changed: '+name
        gate = ROOT/'audit/2026-11-21-release-2.0.0/工作目录/002-发布门控/release-gate-v1.json'
        assert digest(gate) == 'fea2dc76f1ef3374423830101703c9ab90c2ca50ef48b9ee832b5c3d6eaf5b75'
        approved = json.loads(gate.read_text())
        for name, value in approved['evidence_files_sha256'].items():
            assert digest(Path(name)) == value, 'Approved bytes changed: '+name
        proof['approved_release_files_preserved'] = len(approved['evidence_files_sha256'])
        commands = CodeBlocks()
        commands.feed((OUT/NAMES[2]).read_text())
        checks = []
        for block in commands.blocks:
            child = subprocess.run(['bash', '-n'], input=block, capture_output=True, text=True)
            checks.append(dict(sha256=sha256(block.encode()).hexdigest(), actual_returncode=child.returncode,
                               scope='syntax only; no package install, model loading or user-data access'))
            assert child.returncode == 0, child.stderr
            if "python - <<'PY'" in block:
                ast.parse(block.split("python - <<'PY'\n", 1)[1].rsplit('\nPY', 1)[0])
        proof['manual_command_syntax'] = checks
        env = dict(os.environ, LLM_API_KEY='', EMBEDDING_MODEL='',
                   HHU_AVATAR_DATA_ROOT=str(ASSETS), PYTHONDONTWRITEBYTECODE='1',
                   PLAYWRIGHT_BROWSERS_PATH=str(ASSETS/'runtime/playwright'),
                   FONTCONFIG_FILE=str(ASSETS/'runtime/browser-libs/fontconfig.xml'))
        env['LD_LIBRARY_PATH'] = str(ASSETS/'runtime/browser-libs/extracted/usr/lib/x86_64-linux-gnu')+os.pathsep+env.get('LD_LIBRARY_PATH', '')
        installed = ASSETS/'envs/hhu-ai-avatar-release-final-v7/bin'
        cli_rows = []
        # These three commands are read-only; prevent new bytecode writes explicitly.
        for args_cli in [('--version',), ('doctor', '--require-ui'), ('web', '--help')]:
            child = subprocess.run([str(installed/'python'), '-I', '-B', str(installed/'hhu-avatar'), *args_cli],
                                   cwd=ASSETS, env=env, capture_output=True, text=True)
            assert child.returncode == 0, child.stderr
            if args_cli[0] == '--version':
                assert child.stdout.strip() == '2.0.0'
            elif args_cli[0] == 'doctor':
                value = json.loads(child.stdout)
                assert value['core_ready'] and value['frontend']['available'] and value['version'] == '2.0.0'
            else:
                assert all(x in child.stdout for x in ('--db', '--port', '--asr-model', '--asr-backend', '--asr-device'))
            cli_rows.append(dict(argv=list(args_cli), actual_returncode=child.returncode,
                                 stdout_sha256=sha256(child.stdout.encode()).hexdigest()))
        proof['actual_installed_readonly_cli'] = cli_rows
        child = subprocess.run([str(ASSETS/'runtime/node-npm/node_modules/node/bin/node'),
                                str(HERE/'qa_reports.cjs'), str(raw)], cwd=ROOT, env=env,
                               capture_output=True, text=True)
        raw.mkdir(exist_ok=True)
        (raw/'stdout.log').write_text(child.stdout)
        (raw/'stderr.log').write_text(child.stderr)
        proof['steps'].append(dict(name='actual_browser', actual_returncode=child.returncode))
        proof['browser'] = json.loads((raw/'result.json').read_text())
        assert child.returncode == 0 and proof['browser']['passed'], 'Browser failure retained'
        assert all(digest(ROOT/name) == value for name, value in proof['source_sha256'].items())
        # Recheck after actual installed CLI/browser work, not only before it.
        for name, value in approved['evidence_files_sha256'].items():
            assert digest(Path(name)) == value, 'Approved bytes changed during checks: '+name
        proof['passed'] = True
    except BaseException as error:
        proof['error'] = repr(error)
        raise
    finally:
        proof['raw'] = str(raw)
        proof['raw_sha256'] = {str(f.relative_to(raw)): digest(f) for f in raw.rglob('*') if f.is_file()} if raw.exists() else {}
        with proof_path.open('x') as stream:
            json.dump(proof, stream, ensure_ascii=False, indent=2)
            stream.write('\n')
        print(json.dumps({k:v for k,v in proof.items() if k not in ('source_sha256','raw_sha256','browser')}, ensure_ascii=False))


if __name__ == '__main__':
    main()
